import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import extractText from 'flarum/common/utils/extractText';
import Rail from './Rail';
import Heads from './Heads';
import ChatWindow from './ChatWindow';
import { DOCK_BREAKPOINT } from '../state';
const t = (key, params) => app.translator.trans('ernestdefoe-parley.forum.' + key, params);

/**
 * Everything Parley draws over the forum: the rail, the heads, the dock, and
 * the "N online" pill that brings the rail back when it is hidden or the
 * screen is too narrow to dock it.
 */
export default class Parley extends Component {
  oncreate(vnode) {
    super.oncreate(vnode);
    this.sync();
  }
  onupdate(vnode) {
    super.onupdate(vnode);
    this.sync();
  }

  /** The page makes room for the docked rail; the class lives on <body>. */
  sync() {
    const docked = app.parley.railDocked();
    document.body.classList.toggle('Parley--docked', docked);
  }
  view() {
    const s = app.parley;
    const docked = s.railDocked();
    const showRail = docked || s.railSheet;
    const onInbox = app.current && app.current.get && app.current.get('routeName') === 'parley.inbox';
    const total = s.totalUnread();
    return m("div", {
      className: 'Parley' + (docked ? ' docked' : '') + (s.railSheet ? ' sheet' : '')
    }, showRail ? m(Rail, null) : null, !onInbox ? m(Heads, null) : null, !onInbox ? m("div", {
      className: "pl-dock"
    }, s.open.map(id => m(ChatWindow, {
      key: id,
      id: id
    }))) : null, !showRail ? m("button", {
      className: "pl-peek",
      onclick: () => s.toggleRail(),
      "aria-label": extractText(t('rail.show'))
    }, m("span", {
      className: "pl-peek-dot"
    }), m("span", null, t('rail.peek', {
      count: s.online.length
    }), total ? [' · ', t('rail.peek_unread', {
      count: total
    })] : null)) : null);
  }
}
export { DOCK_BREAKPOINT };
flarum.reg.add('ernestdefoe-parley', 'forum/components/Parley', Parley);